import{_ as t,o,c as a,a3 as i}from"./chunks/framework.B_jDsKE8.js";const f=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),d={name:"explanation/concepts.md"};function c(n,e,r,s,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>The age keypair — an <code>x25519::Identity</code> (secret) and its <code>x25519::Recipient</code> (public, the <code>age1…</code> string). One identity decrypts everything sealed to its recipient. tardigrada holds exactly one per machine — in the configured backend.</p><h2 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h2><p>Where the identity lives. <code>TARDIGRADA_IDENTITY_BACKEND</code> selects it (cuora&#39;s model):</p><ul><li><strong><code>keyring</code></strong> (default) — the platform session secret store (secret-service / Keychain / Credential Manager), entry <code>tardigrada/age-identity</code>. Fail closed: no reachable store is an error, never a silent keyfile read.</li><li><strong><code>auto</code></strong> — keyring when reachable, keyfile fallback (a degraded session notes it on stderr, never crashes).</li><li><strong><code>file</code></strong> — the keyfile only; the store is never probed.</li></ul><p>An explicit <code>--identity-file</code>/<code>TARDIGRADA_IDENTITY_FILE</code> pin always means file. <code>backend</code> reports the resolved backend, the configured mode, and the pin state.</p><h2 id="keyfile-identity-txt" tabindex="-1">Keyfile / <code>identity.txt</code> <a class="header-anchor" href="#keyfile-identity-txt" aria-label="Permalink to &quot;Keyfile / `identity.txt`&quot;">​</a></h2><p>The on-disk form: <code>#</code> comment lines (including the public recipient) plus one <code>AGE-SECRET-KEY-…</code> line — the format rage and cuora&#39;s <code>cuora-identity-file</code> both read. Written mode <code>0600</code>, parents created, fsync&#39;d. <code>init</code> never overwrites; <code>import</code> does, deliberately. Keyfiles remain fully supported — the <code>file</code> backend (and <code>auto</code>&#39;s fallback) reads them, and <code>init</code> under <code>keyring</code>/<code>auto</code> adopts an existing keyfile identity into the store rather than orphaning it.</p><h2 id="recipient" tabindex="-1">Recipient <a class="header-anchor" href="#recipient" aria-label="Permalink to &quot;Recipient&quot;">​</a></h2><p>The public half — <code>age1…</code>. Safe to share, print, commit-adjacent (configs, manifests). <code>tardigrada show</code> prints it bare on stdout.</p><h2 id="resolution-order" tabindex="-1">Resolution order <a class="header-anchor" href="#resolution-order" aria-label="Permalink to &quot;Resolution order&quot;">​</a></h2><p>The keyfile path, first hit wins (the <code>file</code> backend and <code>auto</code> fallback — via <code>cuora-identity-file</code>&#39;s shared default, which also resolves legacy <code>cuora</code>/<code>arca</code> keyfiles):</p><ol><li><code>--identity-file PATH</code> (global flag)</li><li><code>TARDIGRADA_IDENTITY_FILE</code></li><li><code>CUORA_IDENTITY_FILE</code> / <code>ARCA_IDENTITY_FILE</code> (legacy overrides)</li><li><code>&lt;config&gt;/tardigrada|cuora|arca/identity.txt</code> — first existing, tardigrada canonical first</li><li>creation target: <code>&lt;config&gt;/tardigrada/identity.txt</code> (<code>$XDG_CONFIG_HOME</code> → <code>~/.config</code>)</li></ol><h2 id="cryptobiosis" tabindex="-1">Cryptobiosis <a class="header-anchor" href="#cryptobiosis" aria-label="Permalink to &quot;Cryptobiosis&quot;">​</a></h2><p>The namesake: the tardigrade&#39;s dormant survival state. The identity equivalent — key material asleep in a <code>0600</code> file, persisting across reboots, tool upgrades, and machine migrations until an encrypted store wakes it.</p>',16)])])}const y=t(d,[["render",c]]);export{f as __pageData,y as default};
